package com.hau.notification.infrastructure.websocket;import com.hau.notification.application.port.out.RealtimeNotifier;import com.hau.notification.domain.model.Notification;import com.hau.notification.presentation.response.NotificationResponse;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Component;
@Component public class StompRealtimeNotifier implements RealtimeNotifier{private final SimpMessagingTemplate template;public StompRealtimeNotifier(SimpMessagingTemplate t){template=t;}public void send(Notification n){template.convertAndSendToUser(n.getUserId().toString(),"/queue/notifications",NotificationResponse.from(n));}}
